nested_dict = {"name": "John", "address": {"street": "123 Main St", "city": "New York"}}
flat_dict = flatten_dict(nested_dict)
print(flat_dict)  # Output: {'name': 'John', 'address.street': '123 Main St', 'address.city': 'New York'}
